import{_ as e,o,c as l,ai as i}from"./chunks/framework.CGsC_gYW.js";const q=JSON.parse('{"title":"常见问题","description":"","frontmatter":{"title":"常见问题"},"headers":[],"relativePath":"qiantao/faq.md","filePath":"qiantao/faq.md","lastUpdated":1792576248000}'),r={name:"qiantao/faq.md"};function d(t,a,c,n,h,s){return o(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="klkhk-plugin-qiandao-1-12-2-·-常见问题" tabindex="-1">[klkhk]plugin_qiandao_1.12.2 · 常见问题 <a class="header-anchor" href="#klkhk-plugin-qiandao-1-12-2-·-常见问题" aria-label="Permalink to &quot;[klkhk]plugin_qiandao_1.12.2 · 常见问题&quot;">​</a></h1><blockquote><p>说实话，九成的问题出在两件事上：<strong>版本不对</strong>，或者<strong>改完没重载</strong>。先排除这两条，再看下面的分类。</p></blockquote><h2 id="安装与启动" tabindex="-1">安装与启动 <a class="header-anchor" href="#安装与启动" aria-label="Permalink to &quot;安装与启动&quot;">​</a></h2><h3 id="插件名显示红色-加载失败" tabindex="-1">插件名显示红色 / 加载失败 <a class="header-anchor" href="#插件名显示红色-加载失败" aria-label="Permalink to &quot;插件名显示红色 / 加载失败&quot;">​</a></h3><ul><li>确认服务端是 <strong>1.12.2</strong>，核心是 Spigot 或 Paper</li><li>确认 Java ≥ 8</li><li>看控制台完整报错。<code>Unsupported class file major version</code> 是 Java 太低，<code>NoClassDefFoundError</code> 通常是核心版本不匹配</li><li>jar 下载不完整也会这样，重新下一遍最快</li></ul><h3 id="启动后没有生成-config-yml" tabindex="-1">启动后没有生成 config.yml <a class="header-anchor" href="#启动后没有生成-config-yml" aria-label="Permalink to &quot;启动后没有生成 config.yml&quot;">​</a></h3><p>先确认插件真的加载了 —— 控制台应该有 <code>QianDao 签到插件已启用</code>。如果没这行，就是 jar 没被识别；如果有这行但没文件，检查 <code>plugins/</code> 的写权限。</p><hr><h2 id="签到与奖励" tabindex="-1">签到与奖励 <a class="header-anchor" href="#签到与奖励" aria-label="Permalink to &quot;签到与奖励&quot;">​</a></h2><h3 id="签到成功-但金币没到账" tabindex="-1">签到成功，但金币没到账 <a class="header-anchor" href="#签到成功-但金币没到账" aria-label="Permalink to &quot;签到成功，但金币没到账&quot;">​</a></h3><p>按顺序查：</p><ol><li>启动日志里 <code>金币联动:</code> 后面是什么。<code>已关闭</code> 就是没检测到前置</li><li><code>economy.type</code> 写的是不是已安装的那个（<code>zpoints</code> / <code>playerpoints</code> / <code>vault</code>）</li><li>前置装好后执行 <code>/qd reload</code>，再签一次</li></ol><p>金币不到账不影响物品奖励，这两条线是分开的。</p><h3 id="改了奖励物品-游戏里没变化" tabindex="-1">改了奖励物品，游戏里没变化 <a class="header-anchor" href="#改了奖励物品-游戏里没变化" aria-label="Permalink to &quot;改了奖励物品，游戏里没变化&quot;">​</a></h3><ul><li>有没有执行 <code>/qd reload</code></li><li><code>cycle</code> 对应天的 <code>commands</code> 写对没有，<code>%player%</code> 不能丢</li><li>指令是控制台执行的，看看控制台有没有报「未知指令」—— 很可能是某个指令插件没装</li></ul><h3 id="第-8-天为什么回到第-1-天奖励" tabindex="-1">第 8 天为什么回到第 1 天奖励 <a class="header-anchor" href="#第-8-天为什么回到第-1-天奖励" aria-label="Permalink to &quot;第 8 天为什么回到第 1 天奖励&quot;">​</a></h3><p>设计如此。7 天一个周期，第 8 天从第 1 天重新开始，但<strong>连续天数继续累计</strong>，所以里程碑（7 / 14 / 30 天）照常触发。</p><h3 id="连续天数突然归零" tabindex="-1">连续天数突然归零 <a class="header-anchor" href="#连续天数突然归零" aria-label="Permalink to &quot;连续天数突然归零&quot;">​</a></h3><p>连续链必须以「今天」或「昨天」结尾。超过一天没签，就判定为断签，连续天数归零，里程碑记录也重新算。这是签到插件该有的严格，不然补签卡就没意义了。</p><hr><h2 id="补签" tabindex="-1">补签 <a class="header-anchor" href="#补签" aria-label="Permalink to &quot;补签&quot;">​</a></h2><h3 id="补签面板里没有可选日期" tabindex="-1">补签面板里没有可选日期 <a class="header-anchor" href="#补签面板里没有可选日期" aria-label="Permalink to &quot;补签面板里没有可选日期&quot;">​</a></h3><p>补签只列出同时满足三个条件的日期：</p><ul><li>最近 <code>buqian.max-days</code> 天内</li><li>在该玩家<strong>首次签到之后</strong></li><li>当天既没正常签到，也没补签过</li></ul><p>新玩家没有历史记录，自然一个都没有。</p><h3 id="补签卡从哪来" tabindex="-1">补签卡从哪来 <a class="header-anchor" href="#补签卡从哪来" aria-label="Permalink to &quot;补签卡从哪来&quot;">​</a></h3><p>三个来源：在线奖励（<code>online-reward</code>）、管理员 <code>/qd givecard &lt;玩家&gt; [数量]</code>、活动发放。</p><h3 id="补签了-连续天数还是没接上" tabindex="-1">补签了，连续天数还是没接上 <a class="header-anchor" href="#补签了-连续天数还是没接上" aria-label="Permalink to &quot;补签了，连续天数还是没接上&quot;">​</a></h3><p>补签只能补「断掉的那一天」。如果断了三天，只补一天接不上整条链，得把中间几天都补了。</p><hr><h2 id="排行榜" tabindex="-1">排行榜 <a class="header-anchor" href="#排行榜" aria-label="Permalink to &quot;排行榜&quot;">​</a></h2><h3 id="右侧计分板不显示" tabindex="-1">右侧计分板不显示 <a class="header-anchor" href="#右侧计分板不显示" aria-label="Permalink to &quot;右侧计分板不显示&quot;">​</a></h3><ul><li><code>ranking.scoreboard-enable</code> 是不是 <code>true</code></li><li>有没有被别的计分板插件顶掉（称号、状态、任务类插件最容易冲突）</li><li><code>/qd reload</code> 会给在线玩家重建计分板，试一次</li></ul><h3 id="某个人不在排行榜上" tabindex="-1">某个人不在排行榜上 <a class="header-anchor" href="#某个人不在排行榜上" aria-label="Permalink to &quot;某个人不在排行榜上&quot;">​</a></h3><p>从未签到过的玩家（连续 0、累计 0）不上榜，这是有意为之，避免新服排行榜全是零。</p><hr><h2 id="配置与升级" tabindex="-1">配置与升级 <a class="header-anchor" href="#配置与升级" aria-label="Permalink to &quot;配置与升级&quot;">​</a></h2><h3 id="升级后配置项丢失-报错" tabindex="-1">升级后配置项丢失 / 报错 <a class="header-anchor" href="#升级后配置项丢失-报错" aria-label="Permalink to &quot;升级后配置项丢失 / 报错&quot;">​</a></h3><p>删掉 <code>plugins/QianDao/config.yml</code> 让插件重新生成，再把自定义内容迁回去。升级前备份是前提，见 <a href="/plugin-wiki/qiantao/install">安装部署</a>。</p><h3 id="能热重载吗" tabindex="-1">能热重载吗 <a class="header-anchor" href="#能热重载吗" aria-label="Permalink to &quot;能热重载吗&quot;">​</a></h3><p><code>/qd reload</code> 可以，会重载配置、重新初始化经济联动、重建计分板。</p><p>但不建议用插件管理器整体重载本插件 —— 定时任务会重复注册，表现为在线奖励发得越来越快。</p><h3 id="支持-1-13-以上吗" tabindex="-1">支持 1.13 以上吗 <a class="header-anchor" href="#支持-1-13-以上吗" aria-label="Permalink to &quot;支持 1.13 以上吗&quot;">​</a></h3><p>当前构建面向 1.12.2，材质名（如 <code>SKULL_ITEM:5</code>）和音效名都是 1.12.2 的。需要其他版本走 <a href="/plugin-wiki/custom">插件定制</a>。</p><hr><h2 id="数据" tabindex="-1">数据 <a class="header-anchor" href="#数据" aria-label="Permalink to &quot;数据&quot;">​</a></h2><h3 id="数据存在哪" tabindex="-1">数据存在哪 <a class="header-anchor" href="#数据存在哪" aria-label="Permalink to &quot;数据存在哪&quot;">​</a></h3><p><code>plugins/QianDao/data.yml</code>，以玩家 UUID 为键，存签到日期、补签日期、累计次数、已发里程碑、在线统计。</p><h3 id="怎么备份-迁移" tabindex="-1">怎么备份 / 迁移 <a class="header-anchor" href="#怎么备份-迁移" aria-label="Permalink to &quot;怎么备份 / 迁移&quot;">​</a></h3><p>复制 <code>config.yml</code> 和 <code>data.yml</code> 到新服务器的同名目录。UUID 不变，数据就通用。</p><h3 id="文件会不会越来越大" tabindex="-1">文件会不会越来越大 <a class="header-anchor" href="#文件会不会越来越大" aria-label="Permalink to &quot;文件会不会越来越大&quot;">​</a></h3><p>不会。超过 60 天的日期记录会自动清理，累计次数和里程碑记录保留。</p><hr><p>还没解决？把控制台报错和 <code>config.yml</code> 相关片段发我：QQ <code>1071576270</code> / <code>1071576270@qq.com</code>。带上报错比描述现象快得多。</p>',54)])])}const p=e(r,[["render",d]]);export{q as __pageData,p as default};
